c.deleted = 0
AND c.owner_id IS NOT NULL


        AND owner.dept_id = #{dataScope.deptId}


        AND c.owner_id = #{dataScope.userId}





        AND 1 = 0

mapper.select:
SELECT CAST(c.id AS CHAR) AS id, c.customer_no AS customerNo, c.customer_name AS customerName, c.customer_type AS customerType, c.customer_level AS customerLevel, c.industry, c.status, CAST(c.owner_id AS CHAR) AS ownerId, owner.real_name AS ownerName, c.updated_at AS updatedAt FROM customer c LEFT JOIN sys_user owner ON owner.id = c.owner_id WHERE
AND (c.customer_no LIKE CONCAT('%', #{query.keyword}, '%') OR c.customer_name LIKE CONCAT('%', #{query.keyword}, '%'))
AND c.customer_level = #{query.customerLevel}
AND c.status = #{query.status}
AND c.customer_type = #{query.customerType}
AND c.owner_id = #{query.ownerId}
ORDER BY c.updated_at DESC, c.id DESC
